    // Read the APE file header block (implementation assumed to be in file_context)
    // Extract properties from the header
    unsigned int totalFrames = readUnsignedIntFromFileHeader();
    unsigned int compressionLevel = readCompressionLevelFromFileHeader();
    unsigned int channels = readChannelsFromFileHeader();
    unsigned int sampleRate = readSampleRateFromFileHeader();

    // Calculate the number of blocks per frame based on version and compression level
    unsigned int blocksPerFrame;
    if (compressionLevel == 0) {
        blocksPerFrame = 1152;
    } else if (compressionLevel <= 4) {
        blocksPerFrame = 576;
    } else {
        blocksPerFrame = 288;
    }

    // Calculate total number of blocks
    unsigned int totalBlocks = totalFrames * blocksPerFrame;

    // Calculate the length of the audio in seconds
    double audioLengthInSeconds = static_cast<double>(totalBlocks) / sampleRate;

    // Calculate the bitrate in kbps
    double bitrateInKbps = (streamLength * 8) / (audioLengthInSeconds * 1000);

    // Update properties with the extracted values
    setTotalFrames(totalFrames);
    setCompressionLevel(compressionLevel);
    setChannels(channels);
    setSampleRate(sampleRate);
    setAudioLengthInSeconds(audioLengthInSeconds);
    setBitrateInKbps(bitrateInKbps);
}

