void APE::Properties::analyzeOld() {
    // Read the header and extract properties
    int total_frames = headerData["total_frames"];
    int compression_level = headerData["compression_level"];
    int channels = headerData["channels"];
    int sample_rate = headerData["sample_rate"];
    int version = headerData["version"];

    // Calculate blocks per frame
    int blocks_per_frame;
    if (version < 3980) {
        blocks_per_frame = 1152;
    } else {
        if (compression_level == 0) {
            blocks_per_frame = 1152;
        } else {
            blocks_per_frame = 128;
        }
    }

    // Calculate total blocks
    int total_blocks = total_frames * blocks_per_frame;

    // Calculate length in seconds and bitrate
    int stream_length = headerData["stream_length"];
    double length_seconds = total_blocks / (double) sample_rate;
    int bitrate = (total_blocks * 1000 * 16) / (stream_length / 1000.0);

    // Update properties
    this->setTotalFrames(total_frames);
    this->setCompressionLevel(compression_level);
    this->setChannels(channels);
    this->setSampleRate(sample_rate);
    this->setLength(length_seconds);
    this->setBitrate(bitrate);
}

