    unsigned int totalFrames = readBigEndianUInt32(0x0C);
    unsigned int compressionLevel = readBigEndianUInt32(0x10);
    unsigned int channels = readBigEndianUInt32(0x14);
    unsigned int sampleRate = readBigEndianUInt32(0x18);

    unsigned int blocksPerFrame = 0;

    if (fileVersion < 3980) {
        if (compressionLevel == 0)
