        else if (compressionLevel == 3)
            blocksPerFrame = 16;
        else if (compressionLevel == 4)
            blocksPerFrame = 8;
        else if (compressionLevel == 5)
            blocksPerFrame = 4;
        else if (compressionLevel == 6)
            blocksPerFrame = 2;
        else if (compressionLevel == 7)
            blocksPerFrame = 1;
    } else {
        if (compressionLevel < 4000)
            blocksPerFrame = 128;
        else if (compressionLevel < 4016)
            blocksPerFrame = 64;
        else if (compressionLevel < 4032)
            blocksPerFrame = 32;
        else if (compressionLevel < 4048)
            blocksPerFrame = 16;
        else if (compressionLevel < 4064)
            blocksPerFrame = 8;
        else if (compressionLevel < 4080)
